import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid={testId}
      data-split-edge-drop-zone="true"
      data-dnd-type={data.type}
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-tab-id={tabId}
      data-leaf-id={leafId}
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edgeHitTargetClass(edge),
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span
          data-testid="split-edge-drop-feedback"
          className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
        >
          New split
        </span>
      ) : null}
    </div>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

import { describe, expect, it } from "vitest";

import {
  dropPriority,
  resolveWorkspaceDropCommand,
  type PaneDragData,
  type TabDragData,
  type WorkspaceDropData,
} from "./tab-dnd/tabDragTypes";

const tabDrag: TabDragData = {
  type: "tab",
  tabId: "tab-source",
  groupId: "group-source",
  index: 0,
};

const paneDrag: PaneDragData = {
  type: "pane",
  tabId: "tab-source",
  leafId: "leaf-source",
};

describe("TerminalSplitView dnd-kit drop resolver", () => {
  it("resolves same-group and cross-group tab targets to one indexed group move", () => {
    expect(
      resolveWorkspaceDropCommand(tabDrag, {
        type: "tab",
        tabId: "tab-target",
        groupId: "group-source",
        index: 2,
      }),
    ).toEqual({
      type: "move-tab-to-group",
      tabId: "tab-source",
      targetGroupId: "group-source",
      targetIndex: 2,
    });

    expect(
      resolveWorkspaceDropCommand(tabDrag, {
        type: "tab",
        tabId: "tab-other",
        groupId: "group-other",
        index: 1,
      }),
    ).toEqual({
      type: "move-tab-to-group",
      tabId: "tab-source",
      targetGroupId: "group-other",
      targetIndex: 1,
    });

    expect(resolveWorkspaceDropCommand(tabDrag, { type: "group-body", groupId: "group-other" })).toEqual({
      type: "move-tab-to-group",
      tabId: "tab-source",
      targetGroupId: "group-other",
    });
  });

  it("maps all four group edges to the canonical split direction and position", () => {
    const expected = {
      left: ["horizontal", "first"],
      right: ["horizontal", "second"],
      top: ["vertical", "first"],
      bottom: ["vertical", "second"],
    } as const;

    for (const [edge, [direction, position]] of Object.entries(expected)) {
      expect(
        resolveWorkspaceDropCommand(tabDrag, {
          type: "group-edge",
          groupId: "group-target",
          edge: edge as "left" | "right" | "top" | "bottom",
        }),
      ).toEqual({
        type: "move-tab-to-split",
        tabId: "tab-source",
        targetGroupId: "group-target",
        direction,
        position,
      });
    }
  });

  it("moves a terminal pane to a tab strip/body without cloning PTY ownership", () => {
    expect(
      resolveWorkspaceDropCommand(paneDrag, {
        type: "tab",
        tabId: "tab-target",
        groupId: "group-target",
        index: 2,
      }),
    ).toEqual({
      type: "detach-pane-to-tab",
      sourceTabId: "tab-source",
      leafId: "leaf-source",
      targetGroupId: "group-target",
      targetIndex: 3,
    });

    expect(resolveWorkspaceDropCommand(paneDrag, { type: "group-body", groupId: "group-target" })).toEqual({
      type: "detach-pane-to-tab",
      sourceTabId: "tab-source",
      leafId: "leaf-source",
      targetGroupId: "group-target",
    });
  });

  it("keeps pane swaps inside their source tab and ignores pane-to-group-edge split", () => {
    expect(
      resolveWorkspaceDropCommand(paneDrag, {
        type: "pane-leaf",
        tabId: "tab-source",
        leafId: "leaf-other",
      }),
    ).toEqual({
      type: "swap-panes",
      tabId: "tab-source",
      sourceLeafId: "leaf-source",
      targetLeafId: "leaf-other",
    });

    expect(
      resolveWorkspaceDropCommand(paneDrag, {
        type: "pane-leaf",
        tabId: "tab-other",
        leafId: "leaf-other",
      }),
    ).toBeNull();
    expect(
      resolveWorkspaceDropCommand(paneDrag, {
        type: "group-edge",
        groupId: "group-target",
        edge: "right",
      }),
    ).toBeNull();
  });

  it("prioritizes edge split over tab insertion over group-body drop for tab drags", () => {
    const edge: WorkspaceDropData = { type: "group-edge", groupId: "group-target", edge: "left" };
    const tab: WorkspaceDropData = { type: "tab", tabId: "tab-target", groupId: "group-target", index: 0 };
    const body: WorkspaceDropData = { type: "group-body", groupId: "group-target" };

    expect(dropPriority(tabDrag, edge)).toBeLessThan(dropPriority(tabDrag, tab));
    expect(dropPriority(tabDrag, tab)).toBeLessThan(dropPriority(tabDrag, body));
  });
